sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 center;
uniform float amount;
uniform float radius;
uniform float reach;
uniform float curve;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float r = max(radius * (reach > 0.5 ? min(screen.z, screen.w) : min(size.x, size.y)), 0.0001);
    float a = curve > 0.5 ? clamp(amount, -4.0, 1.0) : clamp(amount, -1.0, 1.0);
    float len = length(d);
    if (curve > 0.5) {
        if (len >= r) return image.eval(coord);
        float u = len / r;
        if (a < 0.0) return image.eval(c + d / max(len, 0.0001) * (r * (u * u + (1.0 - u) * pow(max(u, 0.0001), 1.0 + 0.75 * a))));
        float q = u * u;
        return image.eval(c + d * (1.0 - 0.75 * a * (1.0 - q * q * (3.0 - 2.0 * q))));
    }
    if (a < 0.0 && len < r) {
        float u = len / r;
        return image.eval(c + d / max(len, 0.0001) * (r * pow(u, 1.0 + 0.77 * a * (1.0 - u))));
    }
    float t = clamp(1.0 - len / r, 0.0, 1.0);
    float k = max(1.0 - a * t * t, 0.0);
    k *= k;
    return image.eval(c + d * k * k);
}
